 const names=(await actualTextBounds(p)).filter(f=>['sellerName','buyerName','certSellerName','certBuyerName'].includes(f.key));
 for(const image of images){assert(image.loaded,'Seal must decode before printing');assert.equal(image.fit,'contain','Original company seal aspect must be preserved');assert(Math.abs(image.box[3]-image.box[1]-28.5)<.7,'Every stamp must be 150% of the former 19pt height');const box=SEAL_SLOTS[image.slot];assert(box,'Unknown seal slot');assert(image.box[0]>=box[0]-.8&&image.box[1]>=box[1]-.8&&image.box[2]<=box[2]+.8&&image.box[3]<=box[3]+.8,'Seal must stay in the original signature area: '+JSON.stringify(image));for(const name of names){const n=name.sourceInk,b=image.box;assert(!(b[0]<n.right&&b[2]>n.x&&b[1]<n.bottom&&b[3]>n.y),'Seal must not cover an entered name: '+JSON.stringify({image,name}));}}
