function assertPdfSeals(audit,slots){
 assert.equal(audit.pages,2);assert.equal(audit.images[0].length,slots.length,'PDF must embed every selected seal in the front sheet');assert.equal(audit.images[1].length,0,'Original reverse sheet must not acquire a seal');
 // The source legal form uses 595×841 points; Chromium's A4 sheet is about 595×842.
 // Compare original and entered text in that same source coordinate system.
 const sx=595/audit.sizes[0][0],sy=841/audit.sizes[0][1],normalize=b=>[b[0]*sx,b[1]*sy,b[2]*sx,b[3]*sy,...b.slice(4)],unused=[...slots],allowed=new Set(['(서명','또는','인)']);
 const words=[...audit.originalWords,...audit.fieldWords[0].map(normalize)];
 for(const image of audit.images[0]){
  const raw=image.bbox,b=normalize(raw),index=unused.findIndex(slot=>{const box=SEAL_SLOTS[slot];return b[0]>=box[0]-1&&b[1]>=box[1]-1&&b[2]<=box[2]+1&&b[3]<=box[3]+1;});assert(index>=0,'PDF seal outside original signature slots: '+JSON.stringify(image));unused.splice(index,1);
  assert(Math.abs(raw[3]-raw[1]-28.5)<1,'PDF must preserve the requested 150% stamp height');assert(Math.abs((raw[2]-raw[0])/(raw[3]-raw[1])-image.width/image.height)<.1,'PDF seal aspect ratio must match the original asset');
  for(const word of words){
   if(allowed.has(word[4])&&Object.values(SEAL_SLOTS).some(s=>word[0]>=s[0]-2&&word[2]<=s[2]+2&&word[1]>=s[1]-2&&word[3]<=s[3]+2))continue;
   const overlapX=Math.min(b[2],word[2])-Math.max(b[0],word[0]),overlapY=Math.min(b[3],word[3])-Math.max(b[1],word[1]);
   // Font metrics extend past real glyph ink by up to 0.8pt; the independent
   // final-PDF raster audit checks the sub-point footer/date clearance.
   assert(overlapX<=.1||overlapY<=.8,'Enlarged seal must not cover original non-signature text or entered data: '+JSON.stringify({image,word}));
  }
 }
 assert.equal(unused.length,0);
}
