async function main(){for(const[file,hash]of[['vehicle-transfer-dealer-2021.pdf','6a17600e22a67af7edf98579a0cc83ec211ab8b40aaaa3adb7b666d61ee22b70'],['vehicle-transfer-front.svg','e51a2d6bdb719457fa687e4949f721791479a6543aa405957509b60b047d6da0'],['vehicle-transfer-back.svg','cbc79796facfcd2624b3f1fa9f2837178f17ef5c3321e58bea6d0e6e871b1dd4']])assert.equal(crypto.createHash('sha256').update(fs.readFileSync(path.join(ROOT,'assets/forms',file))).digest('hex'),hash,'Original legal PDF and independently regenerated SVGs must stay byte-identical');const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium'});setBrowser(browser);try{for(const width of[1440,390])for(const kind of['purchase','sale'])await run(width,kind);fs.writeFileSync(path.join(OUT,'geometry.json'),JSON.stringify(geometryResults,null,2)+'\n');}finally{await browser.close();}}
if(require.main===module)main().catch(error=>{console.error(error.stack);process.exitCode=1;});
